namespace kstation {
class UiEncoderTask final {
public:enum class Stage{ReadCounter,HalfCounter,ReadHalfHistory,WriteHalfHistory,DifferenceHalf,SelectHalfSign,NegateHalf,ReadAcceleration,AddAcceleration,SelectIdle,DecrementAcceleration,CompareAcceleration,SelectAcceleration,ClampAcceleration,WriteAcceleration,BiasValue,SubtractBias,SelectBias,ClampBias,IncrementGain,QuarterCounter,CopyQuarter,ReadQuarterHistory,WriteQuarterHistory,DifferenceQuarter,SelectUnchanged,ReadDirection,WriteDirection,CompareDirection,SelectDirection,ClearAcceleration,WriteClearedAcceleration,IncrementAfterDirection,TestDirection,SelectSign,NegateGain,PublishDelta,Return,Complete};enum class Read{Counter,Half,Acceleration,Quarter,Direction};enum class Write{Half,Acceleration,Quarter,Direction};Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}unsigned result()const{return delta_;}unsigned nextClocks(const FlashCredits&c)const{switch(stage_){case Stage::ReadCounter:return 6+c.read;case Stage::ReadHalfHistory:case Stage::ReadAcceleration:case Stage::ReadQuarterHistory:case Stage::ReadDirection:return 9+c.read;case Stage::WriteHalfHistory:case Stage::WriteAcceleration:case Stage::WriteQuarterHistory:case Stage::WriteDirection:case Stage::WriteClearedAcceleration:return 9+c.write;case Stage::Return:return c.ret;case Stage::Complete:return 0;default:return 3;}}template<class R,class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,R&&read,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;auto next=Stage(unsigned(stage_)+1);switch(stage_){case Stage::ReadCounter:counter_=uint16_t(read(Read::Counter));break;case Stage::HalfCounter:counter_>>=1;break;case Stage::ReadHalfHistory:history_=uint8_t(read(Read::Half));break;case Stage::WriteHalfHistory:write(Write::Half,uint8_t(counter_));break;case Stage::DifferenceHalf:magnitude_=uint8_t(history_-uint8_t(counter_));break;case Stage::SelectHalfSign:if(!(magnitude_&128))next=Stage::ReadAcceleration;break;case Stage::NegateHalf:magnitude_=uint8_t(0u-magnitude_);break;case Stage::ReadAcceleration:acceleration_=uint8_t(read(Read::Acceleration));break;case Stage::AddAcceleration:magnitude_+=acceleration_;break;case Stage::SelectIdle:if(!magnitude_)next=Stage::WriteAcceleration;break;case Stage::DecrementAcceleration:--magnitude_;break;case Stage::SelectAcceleration:if(magnitude_<=13)next=Stage::WriteAcceleration;break;case Stage::ClampAcceleration:magnitude_=13;break;case Stage::WriteAcceleration:write(Write::Acceleration,magnitude_);break;case Stage::SubtractBias:magnitude_=uint8_t(magnitude_-4);break;case Stage::SelectBias:if(!(magnitude_&128))next=Stage::IncrementGain;break;case Stage::ClampBias:magnitude_=0;break;case Stage::IncrementGain:++magnitude_;break;case Stage::QuarterCounter:counter_>>=1;break;case Stage::ReadQuarterHistory:history_=uint8_t(read(Read::Quarter));break;case Stage::WriteQuarterHistory:write(Write::Quarter,uint8_t(counter_));break;case Stage::DifferenceQuarter:delta_=uint8_t(history_-uint8_t(counter_));break;case Stage::SelectUnchanged:if(!delta_)next=Stage::Return;break;case Stage::ReadDirection:direction_=uint8_t(read(Read::Direction));break;case Stage::WriteDirection:write(Write::Direction,delta_);break;case Stage::CompareDirection:direction_^=delta_;break;case Stage::SelectDirection:if(!(direction_&128))next=Stage::TestDirection;break;case Stage::ClearAcceleration:magnitude_=0;break;case Stage::WriteClearedAcceleration:write(Write::Acceleration,0);break;case Stage::IncrementAfterDirection:++magnitude_;break;case Stage::SelectSign:if(!(delta_&128))next=Stage::PublishDelta;break;case Stage::NegateGain:magnitude_=uint8_t(0u-magnitude_);break;case Stage::PublishDelta:delta_=magnitude_;break;default:break;}stage_=next;return cost;}
private:Stage stage_=Stage::ReadCounter;uint16_t counter_=0;uint8_t history_=0,magnitude_=0,acceleration_=0,delta_=0,direction_=0;};
class UiEncoderRouteTask final {
public:enum class Stage{ReadEncoder,TestDelta,SelectDelta,Gate,SelectGate,ReadMode,SelectMode,ClearSelection,WriteSelection,CompareFirst,SelectFirst,CompareFifth,SelectFifth,FirstDirection,TestSign,SelectSign,SecondDirection,WriteDirection,DisplayTail,CopyEditDelta,EditControl,Edit,EditTail,ReadSelection,SelectSelection,CopyParameterDelta,ParameterControl,ParameterTail,Mode,SelectParameter,CopyDefaultDelta,DefaultControl,DefaultTail,Return,Complete};enum class Read{Mode,Selection};enum class Write{Selection,Direction};Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}bool awaiting()const{return waiting_;}void resume(uint8_t delta=0,uint8_t gate=0){if(stage_==Stage::TestDelta)delta_=delta;if(stage_==Stage::SelectGate)gate_=gate;if(stage_==Stage::SelectParameter)parameter_=gate;waiting_=false;}unsigned delta()const{return delta_;}unsigned mode()const{return mode_;}unsigned parameter()const{return parameter_;}unsigned nextClocks(const FlashCredits&c)const{if(waiting_||complete())return 0;switch(stage_){case Stage::ReadEncoder:case Stage::Gate:case Stage::Mode:case Stage::Edit:return c.call;case Stage::ReadMode:case Stage::ReadSelection:return 9+c.read;case Stage::WriteSelection:case Stage::WriteDirection:return 9+c.write;case Stage::SelectFifth:case Stage::DisplayTail:case Stage::EditTail:case Stage::ParameterTail:case Stage::SelectParameter:case Stage::DefaultTail:return 8;case Stage::Return:return c.ret;default:return 3;}}template<class R,class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,R&&read,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;auto next=Stage(unsigned(stage_)+1);switch(stage_){case Stage::ReadEncoder:case Stage::Gate:case Stage::Mode:case Stage::Edit:waiting_=true;break;case Stage::SelectDelta:if(!delta_)next=Stage::Return;break;case Stage::SelectGate:if(gate_)next=Stage::Return;break;case Stage::ReadMode:mode_=uint8_t(read(Read::Mode));break;case Stage::SelectMode:if(!mode_)next=Stage::ReadSelection;break;case Stage::WriteSelection:write(Write::Selection,0);break;case Stage::SelectFirst:if(mode_==1)next=Stage::CopyEditDelta;break;case Stage::SelectFifth:if(mode_!=5)next=Stage::Complete;break;case Stage::SelectSign:if(delta_&128)next=Stage::WriteDirection;break;case Stage::WriteDirection:write(Write::Direction,delta_&128?1:2);break;case Stage::DisplayTail:case Stage::EditTail:case Stage::ParameterTail:case Stage::DefaultTail:next=Stage::Complete;break;case Stage::ReadSelection:selection_=uint8_t(read(Read::Selection));break;case Stage::SelectSelection:if(!selection_)next=Stage::Mode;break;case Stage::SelectParameter:if(parameter_)next=Stage::Complete;break;case Stage::Return:next=Stage::Complete;break;default:break;}stage_=next;return cost;}
private:Stage stage_=Stage::ReadEncoder;bool waiting_=false;uint8_t delta_=0,gate_=0,mode_=0,selection_=0,parameter_=0;};
}
